/* eslint-disable no-nested-ternary */
import React, { memo, useCallback, useEffect, useMemo } from 'react';
import { useDispatch } from 'react-redux'
import { trackPageViews } from 'redux/actions/trackingReport'

import styled from 'styled-components'
import classNames from 'classnames'
import { Button, Skeleton } from 'antd'
import { isEmpty, clone } from 'lodash'
import { showIntercom } from 'Utils/constants/index'
import { Button as ButtonNew } from 'components/features/events/EventsPageLocked';

import CloseIcon from 'public/static/close-banner.svg'
import { useAISessionWatchlist } from 'components/common/Contexts/AISessionWatchlist';
import { useRestrictionContext } from '../../layout/context/restrictionContext';

const styledButton = {
  padding: "6px 10px",
  margin: "0 6px",
  fontSize: "14px",
  lineHeight: "14px"
}

const LinkButton = styled(Button)`
  border: unset;
  padding: 0;
  > span{
    text-decoration: underline;
    font-size: 14px;
    line-height: 1.5;
    font-weight: 500;
  }
`

const BannerWrapper = styled.div`
.float-open-content{
  color: #253C66;
  font-size: 14px;
}
`

const FreeBannerWrapper = styled.div`
.float-open-content{
  color: #253C66;
  font-size: 14px;
  font-weight: 500;
}
`

const webPlanName = ['Free Plan || Web']

export const BannerForTrial = ({
  currentOrgSubscription,
  isIntegrated,
  expirePlanMsg,
  internalProblemMessage,
  setTrialFlag,
  handleCsrfAndQuoteModelVisible,
  paymentStatus,
  remainingTrial,
  taraTrialExpiryDate,
}) => {
  const dispatch = useDispatch()
  const { setShowPricingModal, selfServeFlag, planFeatureAiSessions } = useRestrictionContext()
  const { setUpgradeModalVisible, totalCredits: monthlyTaraCredit } = useAISessionWatchlist()
  const currentOrg =
    !isEmpty(currentOrgSubscription) && clone(currentOrgSubscription)
  const planName = useMemo(() => currentOrg?.planName || '', [currentOrg]);

  const showPricingPopUp = useCallback(() => {
    setShowPricingModal(true)
    dispatch( trackPageViews( null, {
			eventName: selfServeFlag ? 'wa_see_pricing_clicked' : 'wa_request_pricing_clicked',
			track_type: 'event',
			eventProperty: {
				source: 'banner'
			},
		} ) )
  }, [dispatch, selfServeFlag, setShowPricingModal])

  const handlePaymentBannerClose = useCallback(() => {
    dispatch(setTrialFlag(false))
    if( window && typeof window !== 'undefined' ){
      try {
        window.localStorage.setItem('paymentBannerCloseDate', new Date().toISOString())
      } catch (err) {
        // silent fail
      }
    }
  }, [dispatch, setTrialFlag])

  const handleRequestPricing = useCallback( async (e) =>{ 
    if(remainingTrial['days'] + remainingTrial['hours'] !== 0){
      handleCsrfAndQuoteModelVisible(e)
    }
    showPricingPopUp()
  }, [handleCsrfAndQuoteModelVisible, remainingTrial, showPricingPopUp] )

  const roundDays = useCallback((days, hours) => {
      // Convert the total hours to days
      const totalDays = days + (hours / 24);
    
      // Round the total days to the nearest integer
      const roundedDays = Math.round(totalDays);
    
      // Return the rounded days
      return roundedDays;
    
  }, []) 

  const handleClickContactSales = useCallback( () => {
    showIntercom()
    dispatch( trackPageViews( null, {
			eventName: 'wa_contact_sales_clicked',
			track_type: 'event',
			eventProperty: {},
		} ) )
  }, [ dispatch ] )

  useEffect(() => {
    if (planName && webPlanName.includes(planName)) {
      dispatch(setTrialFlag(false))
    }
  }, [dispatch, planName, setTrialFlag])

  const paymentDueMessages = useMemo(() => {
    switch (paymentStatus?.data?.banner_detail?.status) {
      case 'not_paid':
        return <><b>Service Alert:</b> Access to the service may be restricted due to missed payments. Please settle your outstanding balance or contact <a href='mailto:team@uxcam.com'>team@uxcam.com</a> immediately.</>
      case 'payment_due':
        return <>We're unable to process your payments. Please <ButtonNew style={styledButton} onClick={() => { window.location.href = paymentStatus?.data?.banner_detail?.payment_update_url }}>update your payment details</ButtonNew> or contact <a href='mailto:team@uxcam.com'>team@uxcam.com</a> for assistance.</>
      default:
        return null
    }
  }, [paymentStatus])

  const taraTrialRemainingDays = useMemo(() => {
    if (!taraTrialExpiryDate) return null
    const expiryDate = new Date(taraTrialExpiryDate)
    const now = new Date()
    const diffTime = expiryDate.getTime() - now.getTime()
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24))
    return diffDays > 0 ? diffDays : null
  }, [taraTrialExpiryDate])

  const RenderBanners = useCallback(() => {
    // Priority 1: Payment failed banner
    if( paymentStatus?.data?.show_banner && paymentDueMessages ){
      return <BannerWrapper
      className={classNames(
        'global-float-bar payment-due'
      )}>
         <span className='float-open-content'>
          <strong>{paymentDueMessages}</strong>
          <Button
            icon={<CloseIcon />}
            className='bar-close'
            style={{ top: '0' }}
            onClick={handlePaymentBannerClose}
          />
         </span>
      </BannerWrapper>
    }

    // Priority 2: Trial expires banner
    if(currentOrg.onTrial &&
      remainingTrial &&
      remainingTrial?.['days'] >= 0 &&
      remainingTrial?.['hours'] >= 0){
        if(remainingTrial['days'] + remainingTrial['hours'] !== 0)
          return (
            <BannerWrapper
          className={classNames(
            'global-float-bar',
            {
              'float-bar-closed': expirePlanMsg,
            },
            {
              'trial-warning': remainingTrial?.['days'] <= 3,
            }
          )}
        >
            {
              selfServeFlag === 0 ?
              <Skeleton active paragraph={{rows: 1}} />:
              <p style={{ margin: '0' }}>
                <span className='float-open-content'>
                  {remainingTrial.days >= 1 ? (
                    <>
                      <strong>
                        {`${roundDays(remainingTrial.days, remainingTrial.hours)} ${
                          remainingTrial.days > 1 ? 'days' : 'day'
                        } `}{' '}
                      </strong>{' '}
                      remaining on your free trial.
                    </>
                  ) : remainingTrial.hours >= 1 ? (
                    <>
                      <strong>
                        {`${remainingTrial.hours} ${
                          remainingTrial.hours > 1 ? 'hours' : 'hour'
                        } `}{' '}
                      </strong>{' '}
                      left on your free trial.
                    </>
                  ) : (
                    'Your trial period has now ended. '
                  )}
                  <ButtonNew
                    style={styledButton}
                    onClick={handleRequestPricing}
                  >
                    {selfServeFlag ? "Upgrade now" : "Request pricing"}
                  </ButtonNew>
                  {
                    !selfServeFlag && 
                    <>
                      or{'  '}
                      <LinkButton type='link' onClick={ handleClickContactSales }>
                        contact sales
                      </LinkButton>{' '}
                      to upgrade.
                    </>
                  }
                    <Button
                      icon={<CloseIcon />}
                      className='bar-close'
                      style={{ top: '0' }}
                      onClick={() => dispatch(setTrialFlag(false))}
                    />
                  </span>
                </p>
                }
        </BannerWrapper>
          )
      }

      if(currentOrg.planType === "free" && !webPlanName.includes(planName)){
        return <FreeBannerWrapper
        className={classNames(
          'global-float-bar'
        )}
      > 
        {
          selfServeFlag === 0 ? 
              <Skeleton active paragraph={{ rows: 1 }} /> :
              <span className='float-open-content'>
                {currentOrg.status === "Expired" || currentOrg.status === "Canceled" ?
                  <strong>Your plan was {currentOrg.status === 'Expired' ? 'expired' : 'canceled'}.</strong>
                  : 'You are on the free plan.'
                }
                <ButtonNew
                  style={styledButton}
                  onClick={showPricingPopUp}
                >
                  {selfServeFlag ? "Upgrade now" : "Request pricing"}
                </ButtonNew>
                {
                  !selfServeFlag &&
                  <>
                    or{'  '}
                    <LinkButton type='link' onClick={handleClickContactSales}>
                      contact sales
                    </LinkButton>{' '}
                    to upgrade.
                  </>
                }
                <Button
                  icon={<CloseIcon />}
                  className='bar-close'
                  style={{ top: '0' }}
                  onClick={() => dispatch(setTrialFlag(false))}
                />
              </span>
        }
      </FreeBannerWrapper>
      }

      // Priority 3: Tara trial expires banner
      if(planFeatureAiSessions && taraTrialRemainingDays && monthlyTaraCredit){
        return <BannerWrapper
        className={classNames(
          'global-float-bar tara-trial'
        )}>
           <span className='float-open-content'>
            <strong>{taraTrialRemainingDays} {taraTrialRemainingDays === 1 ? 'day' : 'days'}</strong> remaining on your Tara {monthlyTaraCredit} trial
            <ButtonNew
              style={styledButton}
              onClick={() => setUpgradeModalVisible(true)}
            >
              Upgrade your plan
            </ButtonNew>
            <Button
              icon={<CloseIcon />}
              className='bar-close'
              style={{ top: '0' }}
              onClick={() => dispatch(setTrialFlag(false))}
            />
           </span>
        </BannerWrapper>
      }

      if(currentOrg.status === "Expired" || currentOrg.status === "Canceled"){
        return <BannerWrapper
        className={classNames(
          'global-float-bar'
        )}>
           <span className='float-open-content'>
            <strong>Your plan was { currentOrg.status === 'Expired' ? 'expired' : 'canceled' }.</strong>
            <ButtonNew
              style={styledButton}
              onClick={showPricingPopUp}
            >
              Upgrade now
            </ButtonNew>
            <Button
              icon={<CloseIcon />}
              className='bar-close'
              style={{ top: '0' }}
              onClick={() => dispatch(setTrialFlag(false))}
            />
           </span>
        </BannerWrapper>
      }

      if( selfServeFlag && !isIntegrated){
        return <BannerWrapper
        className={classNames(
          'global-float-bar'
        )}>
           <span className='float-open-content'>
            <strong>Choose a plan that meets your needs.</strong>
            <ButtonNew
              style={styledButton}
              onClick={showPricingPopUp}
            >
              Upgrade now
            </ButtonNew>
            <Button
              icon={<CloseIcon />}
              className='bar-close'
              style={{ top: '0' }}
              onClick={() => dispatch(setTrialFlag(false))}
            />
           </span>
        </BannerWrapper>
      }
      
      return null
  }, [currentOrg.onTrial, currentOrg.planType, currentOrg.status, remainingTrial, planName, paymentStatus?.data?.show_banner, paymentDueMessages, selfServeFlag, isIntegrated, expirePlanMsg, roundDays, handleRequestPricing, handleClickContactSales, dispatch, setTrialFlag, showPricingPopUp, handlePaymentBannerClose, taraTrialRemainingDays, monthlyTaraCredit, planFeatureAiSessions, setUpgradeModalVisible])

  return internalProblemMessage ? (
    <div className={classNames('global-float-bar')}>
      <p style={{ margin: '0' }}>
        <span className='float-open-content'>
          {internalProblemMessage}{' '}
          <a
            onClick={() =>
              typeof window !== 'undefined' &&
              window.Intercom &&
              window.Intercom('show')
            }
            style={{ color: '#fff' }}
          >
            Contact customer success team
          </a>{' '}
        </span>
      </p>
    </div>
  ) : currentOrg && !expirePlanMsg ? (
    <RenderBanners />
  ) : (
    <></>
  )
}
export default memo(BannerForTrial)
